css:
html, body, section, main, aside, .container, .row, .col-sm-9, .package-details-main,
.tab-content, .tab-pane, .sidebar-section, #skippedToContent, footer, .footer {
  background-color: #1e1e1e !important;
  color: #e6e6e6 !important;
}
nav.navbar, nav.navbar a { color: #f0f0f0 !important; }
h1, h2, h3, h4, h5, p, li, label, td, th, span, strong, b, dt, dd {
  color: #e6e6e6 !important;
}
a { color: #6cb6ff !important; }
pre, code, .install-script-row, .install-tabs, .icon-text.alert, .alert, #search {
  background-color: #2a2a2a !important;
  color: #e6e6e6 !important;
  border-color: #3a3a3a !important;
}
.nav-tabs > li > a, .nav-tabs > li > a:hover {
  background-color: #1e1e1e !important;
  color: #e6e6e6 !important;
  border-color: #3a3a3a !important;
}
.nav-tabs > li.active > a, .nav-tabs > li.active > a:hover, .nav-tabs > li.active > a:focus {
  background-color: #2a2a2a !important;
  color: #ffffff !important;
  border-color: #3a3a3a #3a3a3a transparent !important;
}
table, tr, td, th { background-color: transparent !important; border-color: #3a3a3a !important; }
hr, .sidebar-section, .body-tabs { border-color: #3a3a3a !important; }
